<script setup lang="ts">
import DataTable from 'primevue/datatable'; import Column from 'primevue/column'; import Button from 'primevue/button';
import StatusTag from './StatusTag.vue'; import type { RepairRequest } from '../types';
withDefaults(defineProps<{ items:RepairRequest[]; selected?:RepairRequest|null; showPriority?:boolean; audience?:'reporter'|'operations' }>(),{showPriority:true,audience:'operations'});
const emit=defineEmits<{ select:[RepairRequest] }>();
const kst=(iso:string)=>new Intl.DateTimeFormat('ko-KR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'}).format(new Date(iso));
</script>
<template><DataTable :value="items" dataKey="id" size="small" scrollable scrollHeight="520px" :rowClass="r=>r.id===selected?.id?'selected-row':''"><Column v-if="showPriority" header="우선"><template #body="{data}"><span class="priority" :class="data.status==='HUMAN_REVIEW'?'critical':'normal'">{{ data.status==='HUMAN_REVIEW'?'HUMAN':'NORMAL' }}</span></template></Column><Column field="id" header="요청번호"><template #body="{data}"><button class="link-button" @click="emit('select',data)">{{ data.id }}</button><small>{{ kst(data.created_at) }}</small></template></Column><Column field="tail_number" header="기체"><template #body="{data}"><b>{{ data.tail_number }}</b><small>{{ data.aircraft_model }}</small></template></Column><Column field="symptom_text" header="신고 증상" style="min-width:22rem"><template #body="{data}"><span class="truncate">{{ data.symptom_text }}</span></template></Column><Column field="status" header="처리 상태"><template #body="{data}"><StatusTag :status="data.status" :audience="audience"/></template></Column><Column header="상세" style="width:5rem"><template #body="{data}"><Button icon="pi pi-arrow-right" text rounded aria-label="상세 보기" @click="emit('select',data)"/></template></Column></DataTable></template>
